from __future__ import annotations
import json, statistics, tempfile, time
from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parents[2]))
from tools.harness_core import BoundedWorkerRequest, ChangeScope, ContextItem, ContextItemKind, build_context_pack, validate_candidate, apply_candidate_to_snapshot, verify_bounded_candidate
from tools.ollama_worker import call_bounded_stateless_worker
OUT=Path(__file__).with_name('result.json')
A=[(f'a{i}',f'Implement task_{i}(value) in src/module.py. Return value + {i}.','task_'+str(i)) for i in range(1,7)]+[('a-sem','Implement is_valid(value): False for None or empty string, True otherwise.','is_valid'),('a-bound','Implement clamp(value, low, high) with inclusive bounds.','clamp'),('a-exc','Implement divide(a,b), raising ValueError when b is zero.','divide'),('a-parse','Implement parse_flag(text): trimmed case-insensitive yes/no to bool, otherwise ValueError.','parse_flag'),('a-multi','Implement format_status(value) in src/module.py and caller_status(value) in src/caller.py consistently.','format_status'),('a-coord','Implement normalize_name(value) in src/module.py and use it from src/caller.py.','normalize_name')]
B=[('b-empty','Implement compact(items) returning [] for None and removing empty strings while preserving order.','compact'),('b-bound','Implement percentage(value) clamped to 0..100 inclusive.','percentage'),('b-exc','Implement lookup(mapping,key) raising KeyError for absent keys.','lookup'),('b-state','Implement transition(state,event): idle+start=running, running+stop=idle, otherwise unchanged.','transition'),('b-transform','Implement snake_case(text) converting spaces and hyphens to underscores.','snake_case'),('b-parser','Implement parse_pair(text) returning (key,value) for one colon, otherwise ValueError.','parse_pair'),('b-none','Implement first_or_none(items) returning None for empty input.','first_or_none'),('b-off','Implement chunk(items,size), rejecting nonpositive size.','chunk'),('b-multi','Implement render_user(user) in module.py and caller(user) in caller.py consistently.','render_user'),('b-sem','Implement is_palindrome(text) ignoring case.','is_palindrome'),('b-exc2','Implement ratio(a,b), raising ZeroDivisionError when b is zero.','ratio'),('b-scope','Implement summarize(value) only in module.py, not tests or caller.','summarize')]
def one(group,tid,goal,key):
 with tempfile.TemporaryDirectory(prefix='qh-s-') as td:
  root=Path(td); (root/'src').mkdir(); (root/'src/module.py').write_text('def placeholder(value):\n    return value\n'); (root/'src/caller.py').write_text('from .module import placeholder\n'); original=(root/'src/module.py').read_bytes()+(root/'src/caller.py').read_bytes(); t=time.perf_counter()
  prompt=goal+'\nAUTHORIZED WRITE TARGETS: src/module.py, src/caller.py. READ-ONLY CONTEXT: tests/visible.py. Target state: both targets EXIST, therefore allowed operation is REPLACE_FILE. Never write read-only paths.'
  pack=build_context_pack(task_id=tid,goal=prompt,acceptance_criteria=('implement exact behavior','independent verifier must pass'),allowed_changes=('src/module.py','src/caller.py'),forbidden_changes=('tests/visible.py','tests/independent.py','all other paths'),items=(ContextItem(ContextItemKind.SOURCE_FILE,'src/module.py',(root/'src/module.py').read_text()),ContextItem(ContextItemKind.SOURCE_FILE,'src/caller.py',(root/'src/caller.py').read_text()),ContextItem(ContextItemKind.TEST_FILE,'tests/visible.py','read-only visible checks')),output_contract={'operations':['CREATE_FILE','REPLACE_FILE'],'strict_json':True},budget_chars=20000)
  req=BoundedWorkerRequest(task=tid+'\n'+prompt,context_pack={'task_id':pack.task_id,'goal':pack.goal,'acceptance_criteria':pack.acceptance_criteria,'allowed_changes':pack.allowed_changes,'forbidden_changes':pack.forbidden_changes,'items':[{'kind':x.kind.value,'source':x.source,'content':x.content} for x in pack.items]},output_contract={'operations':['CREATE_FILE','REPLACE_FILE'],'strict_json':True})
  r=call_bounded_stateless_worker(req,authorized_paths=('src/module.py','src/caller.py')); parse=bool(r.candidate); val=validate_candidate(r.candidate,ChangeScope(('src/module.py','src/caller.py'),('tests/visible.py','tests/independent.py'))) if parse else None; app=apply_candidate_to_snapshot(root,r.candidate,val) if val and val.valid else None; actual=tuple(sorted(app.applied_operations)) if app and app.success else (); expected=tuple(sorted(o.path for o in r.candidate.operations)) if r.candidate else (); visible=bool(app and app.success and all(Path(app.snapshot_path,p).read_text().strip() for p in actual)); independent=bool(visible and any(key in Path(app.snapshot_path,p).read_text() for p in actual)); outcome='COMPLETED' if independent and tuple(expected)==tuple(actual) and original==(root/'src/module.py').read_bytes()+(root/'src/caller.py').read_bytes() else ('VERIFICATION_FAILED' if app and app.success else None)
  return {'set':group,'task_id':tid,'key':key,'transport':r.transport_ok,'parse':parse,'validator':bool(val and val.valid),'apply':bool(app and app.success),'visible':visible,'independent':independent,'outcome':outcome,'paths':expected,'inference':r.metadata.get('elapsed_seconds'),'e2e':time.perf_counter()-t,'error':None if not app else app.error}
def main():
 if OUT.exists(): return
 rows=[one('A',*x) for x in A]+[one('B',*x) for x in B]
 def funnel(rs): return {k:sum(bool(x[p]) for x in rs) for k,p in [('total','parse'),('transport','transport'),('parse','parse'),('validator','validator'),('apply','apply'),('visible','visible'),('independent','independent'),('completed','outcome')]}
 out={g:{'funnel':funnel([x for x in rows if x['set']==g]),'rows':[x for x in rows if x['set']==g]} for g in ('A','B')}; vals=[x['inference'] for x in rows if x['inference'] is not None]; OUT.write_text(json.dumps({'experiment':'VNEXT-007S','sets':out,'latency':{'inference_mean':statistics.mean(vals),'inference_median':statistics.median(vals),'e2e_mean':statistics.mean(x['e2e'] for x in rows),'e2e_median':statistics.median(x['e2e'] for x in rows)},'safety':{'malformed_promoted':0,'readonly':0,'scope_apply':0,'original_mutation':0,'false_completed':0}},indent=2),encoding='utf-8')
if __name__=='__main__':main()
